'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

function partitions(text, check) {
  for (let first = 0; first <= text.length; first++) {
    for (let second = first; second <= text.length; second++) {
      check(['', text.slice(0, first), '', text.slice(first, second), '', text.slice(second), '']);
    }
  }
  const units = [''];
  for (let index = 0; index < text.length; index++) units.push(text[index], '');
  check(units);
}

test('grammar remains correct at every pair of chunk boundaries', () => {
  const cases = [
    ['', []],
    ['\uFEFF', []],
    ['\n', [['']]],
    ['\r\n\r\n\r\n', [[''], [''], ['']]],
    ['\n\r\r\n\n', [[''], [''], [''], ['']]],
    ['a,b\r\nc,d\re,f\n', [['a', 'b'], ['c', 'd'], ['e', 'f']]],
    ['left,,right,', [['left', '', 'right', '']]],
    [',', [['', '']]],
    ['""', [['']]],
    ['""""', [['"']]],
    ['a"b,a""b, "c"', [['a"b', 'a""b', ' "c"']]],
    ['"a,b","say ""hi"""\r\n', [['a,b', 'say "hi"']]],
    ['"a\r\nb\rc\nd",tail\r\nnext', [['a\r\nb\rc\nd', 'tail'], ['next']]],
    ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
    ['\uFEFF\uFEFF', [['\uFEFF']]],
    ['💡,"😀"\r\nx', [['💡', '😀'], ['x']]],
    ['a;"b;c";\r\n', [['a', 'b;c', '']], { delimiter: ';' }],
    ['a\tb\n', [['a', 'b']], { delimiter: '\t' }],
    ['a b ', [['a', 'b', '']], { delimiter: ' ' }],
    ['a\0b', [['a', 'b']], { delimiter: '\0' }],
    ['\uFEFFa\uFEFFb', [['a', 'b']], { delimiter: '\uFEFF' }],
    ['a💡b', [['a', '\uDCA1b']], { delimiter: '\uD83D' }],
  ];
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, options), expected);
    partitions(text, chunks => {
      const parser = createParser(options);
      const records = chunks.flatMap(chunk => parser.push(chunk));
      records.push(...parser.end());
      assert.deepEqual(records, expected, JSON.stringify({ text, chunks }));
      assert.deepEqual(parser.end(), []);
    });
  }
});

test('push emits immediately at CR and never repeats completed records', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.push('first\r'), [['first']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\nsecond\nthird\r'), [['second'], ['third']]);
  assert.deepEqual(parser.push('\n"fourth\r'), []);
  assert.deepEqual(parser.push('\nline"\r'), [['fourth\r\nline']]);
  assert.deepEqual(parser.push('\nlast,'), []);
  assert.deepEqual(parser.end(), [['last', '']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
});

test('syntax errors report physical lines across all chunk boundaries', () => {
  const cases = [
    ['"a"x', 1, false],
    ['"a" ', 1, false],
    ['"a"\t', 1, false],
    ['a\r\n"b"x', 2, false],
    ['"a\r\nb\rc\nd"x', 4, false],
    ['"a\r\n" x', 2, false],
    ['\n\r\r\n\n"x"!', 5, false],
    ['"', 1, true],
    ['"a\r', 2, true],
    ['"a\r\n', 2, true],
    ['"a\n\r', 3, true],
    ['"a\r\nb\rc\n', 4, true],
    ['"a""', 1, true],
  ];
  for (const [text, line, atEnd] of cases) {
    const matches = error => error instanceof SyntaxError &&
      new RegExp(`\\bline ${line}\\b`).test(error.message);
    assert.throws(() => parse(text), matches);
    partitions(text, chunks => {
      const parser = createParser();
      if (atEnd) {
        for (const chunk of chunks) parser.push(chunk);
        assert.throws(() => parser.end(), matches);
      } else {
        assert.throws(() => {
          for (const chunk of chunks) parser.push(chunk);
        }, matches);
      }
    });
  }
});

test('delimiter validation, string-only input, lifecycle and independent state', () => {
  for (const delimiter of ['', 'ab', '💡', '"', '\r', '\n', null, 1, false, {}, [';']]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
    assert.throws(() => parse('', { delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const first = createParser();
  const second = createParser({ delimiter: ';' });
  for (const chunk of [null, undefined, 1, false, {}, [], Buffer.from('a'), new String('a')]) {
    assert.throws(() => first.push(chunk), TypeError);
    assert.throws(() => parse(chunk), TypeError);
  }
  assert.deepEqual(first.push('"one\r'), []);
  assert.deepEqual(second.push('x;y\r'), [['x', 'y']]);
  assert.deepEqual(first.push('\ntwo"'), []);
  assert.deepEqual(second.push('\nz;w'), []);
  assert.deepEqual(second.end(), [['z', 'w']]);
  assert.deepEqual(first.end(), [['one\r\ntwo']]);
  for (const parser of [first, second]) {
    assert.deepEqual(parser.end(), []);
    assert.throws(() => parser.push(''), Error);
    assert.throws(() => parser.push('extra'), Error);
  }
  const empty = createParser();
  assert.deepEqual(empty.end(), []);
  assert.deepEqual(empty.end(), []);
  assert.throws(() => empty.push(''), Error);
});

test('header integration retains duplicates, padding and safe special keys', () => {
  const options = Object.freeze({ header: true });
  const objects = parse('x,x,x_2,x,__proto__,constructor,toString\n1,2,3,4,p,c,t,extra\nshort', options);
  assert.deepEqual(Object.keys(objects[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString']);
  assert.deepEqual(Object.values(objects[0]), ['1', '2', '3', '4', 'p', 'c', 't']);
  assert.deepEqual(Object.values(objects[1]), ['short', '', '', '', '', '', '']);
  for (const object of objects) {
    assert.equal(Object.getPrototypeOf(object), Object.prototype);
    for (const key of Object.keys(object)) {
      const descriptor = Object.getOwnPropertyDescriptor(object, key);
      assert.equal(descriptor.enumerable, true);
      assert.equal(descriptor.writable, true);
      assert.equal(descriptor.configurable, true);
    }
  }
  assert.deepEqual(parse('', options), []);
  assert.deepEqual(parse('a,b', options), []);
  assert.deepEqual(parse('a,b\n1,2', { header: false }), [['a', 'b'], ['1', '2']]);
  const records = Object.freeze([Object.freeze(['one']), Object.freeze(['two', 'three', 'extra'])]);
  const names = Object.freeze(['a', 'a']);
  assert.deepEqual(toObjects(records, Object.freeze({ header: names })), [
    { a: 'one', a_2: '' }, { a: 'two', a_2: 'three' },
  ]);
  assert.deepEqual(records, [['one'], ['two', 'three', 'extra']]);
  assert.deepEqual(names, ['a', 'a']);
  assert.deepEqual(toObjects(records, { header: Object.freeze([]) }), [{}, {}]);
});

